public static void main(Args _args)
{
    // Instantiate the controller
    SKL_SampleReportController controller = new SKL_SampleReportController();

    // This is the missing link! Point it to your Report and the specific Design
    controller.parmReportName(ssrsReportStr(SKL_SampleReport, Design));

    // Pass the arguments and start the operation
    controller.parmArgs(_args);
    controller.startOperation();
}
